// Non-component helpers for the three-portal features (docs/Three_Portal_Feature_Spec.md).

const friendlyLabel: Record<string, string> = {
  Requested: 'Awaiting doctor',
  Confirmed: 'Confirmed',
  Completed: 'Completed',
  Cancelled: 'Cancelled',
  NoShow: 'No-show',
  Pending: 'Pending',
  Accepted: 'Accepted',
  Declined: 'Declined',
  Expired: 'Expired',
}

export const toneByFriendlyStatus: Record<string, 'muted' | 'primary' | 'warning' | 'success' | 'danger'> = {
  Requested: 'warning',
  Confirmed: 'primary',
  Completed: 'success',
  Cancelled: 'muted',
  NoShow: 'danger',
  Pending: 'warning',
  Accepted: 'success',
  Declined: 'muted',
  Expired: 'muted',
}

export function friendlyStatusLabel(status: string): string {
  return friendlyLabel[status] ?? status.replaceAll(/([a-z])([A-Z])/g, '$1 $2')
}

export function formatDateTime(iso: string): string {
  try {
    return new Date(iso).toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' })
  } catch {
    return iso
  }
}

export function formatDay(iso: string): string {
  try {
    return new Date(iso).toLocaleDateString(undefined, { weekday: 'long', month: 'short', day: 'numeric' })
  } catch {
    return iso
  }
}

export function extractErrorMessage(error: unknown, fallback: string): string {
  const maybeAxios = error as { response?: { data?: { message?: string; errors?: Record<string, string[]> } } }
  const data = maybeAxios?.response?.data
  if (data?.errors) return Object.values(data.errors).flat().join(' ')
  if (data?.message) return data.message
  return fallback
}
